official<-select(org.Hs.eg.db,keys=keys(org.Hs.eg.db,keytype='SYMBOL'),keytype='SYMBOL',columns='ENSEMBL');official<-unique(official[!is.na(official$ENSEMBL),c('SYMBOL','ENSEMBL')]);official_env<-list2env(split(official$ENSEMBL,official$SYMBOL),hash=TRUE,parent=emptyenv())
resolve_annotation<-function(feature,symbol,author_ens=NULL,dataset){
 symbol<-as.character(symbol);symbol[is.na(symbol)]<-'';pieces<-strsplit(symbol,'\\s*(?:///|//|;|,)\\s*',perl=TRUE);tokens<-unique(trimws(unlist(pieces)));tokens<-tokens[nzchar(tokens)]
 unknown<-setdiff(tokens,ls(official_env));valid<-intersect(unknown,keys(org.Hs.eg.db,keytype='ALIAS'));aliases<-if(length(valid))select(org.Hs.eg.db,keys=valid,keytype='ALIAS',columns='ENSEMBL')else data.frame(ALIAS=character(),ENSEMBL=character());aliases<-aliases[!is.na(aliases$ENSEMBL),,drop=FALSE];alias_env<-list2env(split(aliases$ENSEMBL,aliases$ALIAS),hash=TRUE,parent=emptyenv())
 getgene<-function(t){v<-get0(t,envir=official_env,inherits=FALSE);if(is.null(v))v<-get0(t,envir=alias_env,inherits=FALSE);unique(v[!is.na(v)])}
 sy<-vapply(pieces,function(pp){pp<-unique(trimws(pp[nzchar(trimws(pp))]));if(!length(pp))return('');v<-lapply(pp,getgene);if(any(lengths(v)!=1))return('');u<-unique(unlist(v));if(length(u)==1)u else ''},character(1))
 if(is.null(author_ens))author_ens<-rep('',length(feature));author_ens<-as.character(author_ens);author_ens[is.na(author_ens)]<-''
 aa<-regmatches(author_ens,gregexpr('ENSG[0-9]+',author_ens));aa<-lapply(aa,unique);n_ens<-lengths(aa);au<-vapply(aa,function(v)if(length(v)==1)v else '',character(1))
 conflict<-n_ens==1&nzchar(sy)&au!=sy;id<-ifelse(n_ens==1,au,ifelse(n_ens==0,sy,''));id[conflict]<-''
 d<-data.frame(dataset=dataset,feature_id=as.character(feature),source_symbol=symbol,author_ensembl=author_ens,n_author_ensembl=n_ens,symbol_resolved_ensembl=sy,annotation_conflict=conflict,human_ensembl=id,unambiguous=nzchar(id),stringsAsFactors=FALSE)
 # A feature occurring more than once must still resolve to exactly one full-reference gene.
 byid<-split(d$human_ensembl,d$feature_id);bad<-names(byid)[vapply(byid,function(v)length(unique(v[nzchar(v)]))!=1||any(!nzchar(v)),logical(1))];d$unambiguous[d$feature_id%in%bad]<-FALSE;d$human_ensembl[!d$unambiguous]<-'';maps[[dataset]]<<-d;d
}
collapse<-function(x,ann,dataset){
 complete<-rownames(x)[rowSums(is.finite(x))==ncol(x)];ann$complete_expression<-ann$feature_id%in%complete;maps[[dataset]]<<-ann
 a<-unique(ann[ann$unambiguous&ann$complete_expression&ann$human_ensembl%in%core$human_ensembl,c('feature_id','human_ensembl')]);groups<-split(a$feature_id,a$human_ensembl)
 ans<-do.call(rbind,lapply(groups,function(ids){v<-x[unique(ids),,drop=FALSE];if(nrow(v)==1)as.numeric(v[1,])else apply(v,2,median)}));rownames(ans)<-names(groups);colnames(ans)<-colnames(x);ans
}
register<-function(dataset,x,m,ref,method,family){
