 m$dataset<-dataset;m$study_family<-family;m$reference_for_scaling<-ref;sd0<-apply(x[,ref,drop=FALSE],1,sd);pos<-match(core$human_ensembl,rownames(x));scored<-!is.na(pos);scored[scored]<-is.finite(sd0[pos[scored]])&sd0[pos[scored]]>1e-8
 covs[[dataset]]<<-data.frame(dataset=dataset,human_ensembl=core$human_ensembl,display_symbol=core$display_symbol,frozen_direction=core$frozen_direction,present=!is.na(pos),scored=scored,reference_sd=ifelse(is.na(pos),NA,sd0[pos]));objects[[dataset]]<<-list(x=x,meta=m,reference=ref,method=method);norms[[dataset]]<<-data.frame(dataset=dataset,study_family=family,n_profiles=ncol(x),n_reference=sum(ref),n_mapped=nrow(x),n_scored=sum(scored),method=method)
 write.csv(data.frame(human_ensembl=rownames(x),x,check.names=FALSE),gzfile(file.path(OUT,'data/processed',paste0(dataset,'_log_expression.csv.gz'))),row.names=FALSE);write.csv(m,file.path(OUT,'data/processed',paste0(dataset,'_metadata.csv')),row.names=FALSE,na='');message(dataset,': ',ncol(x),'profiles; ',sum(scored),'scored genes')
}
series<-function(file){
 con<-gzfile(file);l<-readLines(con,warn=FALSE);close(con);b<-grep('^!series_matrix_table_begin',l);e<-grep('^!series_matrix_table_end',l);stopifnot(length(b)==1,length(e)==1);d<-read.delim(textConnection(paste(l[(b+1):(e-1)],collapse='\n')),check.names=FALSE,quote='"');x<-as.matrix(d[,-1]);storage.mode(x)<-'double';rownames(x)<-as.character(d[[1]])
 vals<-function(key){v<-l[startsWith(l,paste0(key,'\t'))];lapply(v,function(q)gsub('^"|"$','',strsplit(q,'\t',fixed=TRUE)[[1]][-1]))}
 m<-data.frame(sample_id=vals('!Sample_geo_accession')[[1]],title=vals('!Sample_title')[[1]],stringsAsFactors=FALSE)
 for(v in vals('!Sample_characteristics_ch1')){f<-sub(':.*','',v);value<-sub('^[^:]+:\\s*','',v,perl=TRUE);for(n in unique(f)){col<-make.names(tolower(n));if(!col%in%names(m))m[[col]]<-NA_character_;ix<-which(f==n);m[[col]][ix]<-value[ix]}}
 stopifnot(identical(colnames(x),m$sample_id));list(x=x,meta=m)
}
